import{_ as d,o as r,c as a,a3 as o}from"./chunks/framework.Cc-oPviL.js";const h=JSON.parse('{"title":"速查页 A　ACF/PACF 定阶四象限","description":"","frontmatter":{},"headers":[],"relativePath":"timeseries/12.md","filePath":"timeseries/12.md"}'),e={name:"timeseries/12.md"};function s(l,t,n,i,A,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="速查页-a-acf-pacf-定阶四象限" tabindex="-1">速查页 A　ACF/PACF 定阶四象限 <a class="header-anchor" href="#速查页-a-acf-pacf-定阶四象限" aria-label="Permalink to &quot;速查页 A　ACF/PACF 定阶四象限&quot;">​</a></h1><p>本页把 ACF 与 PACF 的判读规则压缩成一张表和一套步骤，用于建模前的快速判断。</p><h2 id="a1-判读表" tabindex="-1">A1 判读表 <a class="header-anchor" href="#a1-判读表" aria-label="Permalink to &quot;A1 判读表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>序列/模型</th><th>ACF 形态</th><th>PACF 形态</th><th>典型判断</th></tr></thead><tbody><tr><td>白噪声</td><td>全部在置信带内</td><td>全部在置信带内</td><td>无结构可提取，停止建模</td></tr><tr><td>AR(1)</td><td>指数衰减，ρₖ = φᵏ</td><td>滞后 1 后截尾</td><td>一阶自回归</td></tr><tr><td>AR(2)</td><td>指数或振荡衰减</td><td>滞后 2 后截尾</td><td>二阶自回归</td></tr><tr><td>AR(p)</td><td>拖尾</td><td><strong>p 阶截尾</strong></td><td>p 阶自回归</td></tr><tr><td>MA(1)</td><td>滞后 1 后截尾</td><td>指数衰减（交替符号）</td><td>一阶移动平均</td></tr><tr><td>MA(q)</td><td><strong>q 阶截尾</strong></td><td>拖尾</td><td>q 阶移动平均</td></tr><tr><td>ARMA(p,q)</td><td>拖尾</td><td>拖尾</td><td>需信息准则定阶</td></tr><tr><td>随机游走</td><td>极慢衰减，长期贴近 1</td><td>滞后 1 接近 1</td><td>非平稳，需差分</td></tr><tr><td>趋势平稳</td><td>缓慢衰减，可能有振荡</td><td>首阶接近 1 后快速下降</td><td>退势而非差分</td></tr><tr><td>季节序列</td><td>在 s, 2s, 3s 处有尖峰</td><td>在 s 处有尖峰</td><td>加季节项</td></tr></tbody></table><h2 id="a2-判读顺序-建议按此步骤" tabindex="-1">A2 判读顺序（建议按此步骤） <a class="header-anchor" href="#a2-判读顺序-建议按此步骤" aria-label="Permalink to &quot;A2 判读顺序（建议按此步骤）&quot;">​</a></h2><p><strong>第一步：看 ACF 是否衰减到零。</strong></p><ul><li>若在 20 个滞后内仍未落入置信带 → 大概率非平稳，先处理平稳性。</li><li>若快速落入 → 进入第二步。</li></ul><p><strong>第二步：看 ACF 有没有&quot;截尾&quot;点。</strong></p><ul><li>在 q 阶后突然全部落入带内 → 候选 MA(q)。</li><li>没有明显截断、平滑衰减 → 进入第三步。</li></ul><p><strong>第三步：看 PACF 有没有&quot;截尾&quot;点。</strong></p><ul><li>在 p 阶后突然落入带内 → 候选 AR(p)。</li><li>也没有截断 → 候选 ARMA，两者都拖尾。</li></ul><p><strong>第四步：检查季节位置。</strong></p><ul><li>在 s、2s、3s 处有孤立尖峰 → 加季节项。</li></ul><p><strong>第五步：检查过度差分信号。</strong></p><ul><li>差分后 ACF 滞后 1 约 −0.5 → 差分多了。</li></ul><h2 id="a3-四个常见误判" tabindex="-1">A3 四个常见误判 <a class="header-anchor" href="#a3-四个常见误判" aria-label="Permalink to &quot;A3 四个常见误判&quot;">​</a></h2><p><strong>误判一：把&quot;拖尾&quot;当成 ARMA。</strong> 接近单位根的 AR(1)（φ = 0.98）的 PACF 也会缓慢衰减，看起来像拖尾。此时应先做单位根检验，而不是直接上 ARMA。</p><p><strong>误判二：把季节尖峰当成高阶 AR。</strong> 若 ACF 只在滞后 12 处有一个孤立尖峰，中间都为零，这不是 AR(12)，而是季节性。加季节项比加 11 个零系数更简约。</p><p><strong>误判三：忽略置信带的&quot;逐点&quot;性质。</strong> 看 20 个滞后时，即使纯白噪声也平均有 1 个点偶然越界。不要因为单个越界就加阶。</p><p><strong>误判四：用样本 ACF 的&quot;截尾&quot;直接定阶。</strong> 样本 ACF 在 q 阶后通常不会严格为零，而是小幅波动。真正的定阶要靠信息准则或样本外误差。</p>',20)])])}const c=d(e,[["render",s]]);export{h as __pageData,c as default};
